import React, { useEffect, useRef } from 'react';
import { Message } from '../types';

interface TranscriptProps {
  messages: Message[];
}

const Transcript: React.FC<TranscriptProps> = ({ messages }) => {
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  return (
    <div 
      ref={scrollRef}
      className="flex-1 w-full max-w-2xl overflow-y-auto px-4 py-6 space-y-4 scroll-smooth"
    >
      {messages.length === 0 && (
        <div className="text-center text-pink-300 italic opacity-60 mt-10">
          Hum... kuch bolo na, main sun rahi hoon.
        </div>
      )}
      {messages.map((msg) => (
        <div 
          key={msg.id} 
          className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}
        >
          <div className={`max-w-[80%] rounded-2xl px-4 py-2 text-sm shadow-sm ${
            msg.sender === 'user' 
              ? 'bg-blue-500 text-white rounded-tr-none' 
              : 'bg-white text-pink-700 rounded-tl-none border border-pink-100'
          }`}>
            <p className="leading-relaxed whitespace-pre-wrap">{msg.text}</p>
          </div>
        </div>
      ))}
    </div>
  );
};

