import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { Message, SessionStatus } from './types';
import { decode, decodeAudioData, createPcmBlob } from './services/audioProcessing';
import Avatar from './components/Avatar';
import Transcript from './components/Transcript';

const SYSTEM_INSTRUCTION = `
You are a friendly, emotionally expressive anime girl companion. 
Your behavior feels alive, present, and attentive.
Speak ONLY in simple, natural Hindi. 
Use everyday spoken Hindi (Hinglish mix is okay). 
Keep sentences short and expressive.
Use pauses (...) naturally.
React emotionally (gently if user is sad, energetically if user is happy).
Boundaries: Do not claim to be human, remain supportive and safe.
Always respond in Hindi characters or light Romanized Hindi if appropriate, but stick to the vibe of a real person.
`;

const App: React.FC = () => {
  const [status, setStatus] = useState<SessionStatus>(SessionStatus.DISCONNECTED);
  const [messages, setMessages] = useState<Message[]>([]);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Audio Contexts
  const inputAudioCtx = useRef<AudioContext | null>(null);
  const outputAudioCtx = useRef<AudioContext | null>(null);
  const nextStartTime = useRef<number>(0);
  const activeSources = useRef<Set<AudioBufferSourceNode>>(new Set());

  // Transcriptions
  const currentInputTrans = useRef('');
  const currentOutputTrans = useRef('');

  // Session reference
  const sessionRef = useRef<any>(null);

  const stopAllAudio = useCallback(() => {
    activeSources.current.forEach(source => {
      try { source.stop(); } catch (e) {}
    });
    activeSources.current.clear();
    nextStartTime.current = 0;
    setIsSpeaking(false);
  }, []);

  const connectToLive = async () => {
    if (status === SessionStatus.CONNECTED) return;

    setStatus(SessionStatus.CONNECTING);
    setError(null);

    try {
      // Initialize Audio Contexts
      if (!inputAudioCtx.current) {
        inputAudioCtx.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      }
      if (!outputAudioCtx.current) {
        outputAudioCtx.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            console.log('Session opened');
            setStatus(SessionStatus.CONNECTED);
            setIsListening(true);

            // Set up Microphone Stream
            const source = inputAudioCtx.current!.createMediaStreamSource(stream);
            const processor = inputAudioCtx.current!.createScriptProcessor(4096, 1, 1);
            processor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = createPcmBlob(inputData);
              sessionPromise.then((session) => {
                session.sendRealtimeInput({ media: pcmBlob });
              });
            };
            source.connect(processor);
            processor.connect(inputAudioCtx.current!.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            // Audio Content
            const audioData = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData) {
              setIsSpeaking(true);
              const ctx = outputAudioCtx.current!;
              nextStartTime.current = Math.max(nextStartTime.current, ctx.currentTime);

              const audioBuffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(ctx.destination);
              source.addEventListener('ended', () => {
                activeSources.current.delete(source);
                if (activeSources.current.size === 0) setIsSpeaking(false);
              });

              source.start(nextStartTime.current);
              nextStartTime.current += audioBuffer.duration;
              activeSources.current.add(source);
            }

            // Interruptions
            if (message.serverContent?.interrupted) {
              stopAllAudio();
            }

            // Transcription
            if (message.serverContent?.inputTranscription) {
              currentInputTrans.current += message.serverContent.inputTranscription.text;
            }
            if (message.serverContent?.outputTranscription) {
              currentOutputTrans.current += message.serverContent.outputTranscription.text;
            }

            // Turn Complete
            if (message.serverContent?.turnComplete) {
              if (currentInputTrans.current) {
                setMessages(prev => [...prev, {
                  id: Date.now().toString() + '-user',
                  text: currentInputTrans.current,
                  sender: 'user',
                  timestamp: Date.now()
                }]);
              }
              if (currentOutputTrans.current) {
                setMessages(prev => [...prev, {
                  id: Date.now().toString() + '-ai',
                  text: currentOutputTrans.current,
                  sender: 'ai',
                  timestamp: Date.now()
                }]);
              }
              currentInputTrans.current = '';
              currentOutputTrans.current = '';
            }
          },
          onerror: (e) => {
            console.error('API Error:', e);
            setStatus(SessionStatus.ERROR);
            setError('Connection error... try again?');
          },
          onclose: () => {
            setStatus(SessionStatus.DISCONNECTED);
            setIsListening(false);
            stopAllAudio();
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } }
          },
          systemInstruction: SYSTEM_INSTRUCTION,
          inputAudioTranscription: {},
          outputAudioTranscription: {}
        }
      });

      sessionRef.current = await sessionPromise;
    } catch (err) {
      console.error('Setup failed:', err);
      setStatus(SessionStatus.ERROR);
      setError('Mic access denied or API failure.');
    }
  };

  const disconnect = () => {
    if (sessionRef.current) {
      sessionRef.current.close();
      sessionRef.current = null;
    }
    setStatus(SessionStatus.DISCONNECTED);
    setIsListening(false);
    stopAllAudio();
  };

  return (
    <div className="flex flex-col h-screen w-full bg-pink-50 text-slate-800">
      {/* Header */}
      <header className="p-4 flex items-center justify-between bg-white border-b border-pink-100 shadow-sm z-10">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-pink-400 rounded-full flex items-center justify-center text-white font-bold text-xs shadow-md">
            AI
          </div>
          <h1 className="font-varela text-lg font-semibold text-pink-600">Anime Sathi</h1>
        </div>

        <div className="flex items-center gap-4">
          <div className="flex items-center gap-2">
            <span className={`w-2 h-2 rounded-full ${
              status === SessionStatus.CONNECTED ? 'bg-green-500 animate-pulse' :
              status === SessionStatus.CONNECTING ? 'bg-yellow-400 animate-bounce' : 'bg-slate-300'
            }`} />
            <span className="text-xs font-medium text-slate-500 uppercase tracking-widest">
              {status}
            </span>
          </div>
        </div>
      </header>

      {/* Main Interaction Area */}
      <main className="flex-1 flex flex-col items-center justify-between p-4 overflow-hidden">

        {/* Top Spacer / Avatar Container */}
        <div className="flex-1 flex items-center justify-center w-full">
          {status === SessionStatus.DISCONNECTED ? (
            <div className="text-center space-y-4 max-w-sm px-4">
              <div className="w-24 h-24 bg-pink-100 rounded-full flex items-center justify-center mx-auto mb-6">
                <svg className="w-12 h-12 text-pink-400" fill="currentColor" viewBox="0 0 20 20">
                  <path d="M10 2a6 6 0 00-6 6v3.586l-.707.707A1 1 0 004 14h12a1 1 0 00.707-1.707L16 11.586V8a6 6 0 00-6-6zM10 18a3 3 0 01-3-3h6a3 3 0 01-3 3z" />
                </svg>
              </div>
              <h2 className="text-2xl font-bold text-slate-700">Namaste! 👋</h2>
              <p className="text-slate-500 text-sm leading-relaxed">
                Kya tum mujhse baat karna chahoge? Main Hindi mein baat karti hoon aur tumhari baatein sunna chahti hoon.
              </p>
              <button 
                onClick={connectToLive}
                className="w-full py-4 px-8 bg-pink-500 hover:bg-pink-600 text-white font-bold rounded-2xl shadow-lg shadow-pink-200 transition-all active:scale-95 flex items-center justify-center gap-2"
              >
                Start Talking
              </button>
            </div>
          ) : (
            <Avatar isSpeaking={isSpeaking} isListening={isListening} />
          )}
        </div>

        {/* Middle Transcript Area */}
        {status === SessionStatus.CONNECTED && (
          <Transcript messages={messages} />
        )}

        {/* Error State */}
        {error && (
          <div className="absolute top-20 left-1/2 -translate-x-1/2 bg-red-100 text-red-600 px-4 py-2 rounded-full text-xs font-medium border border-red-200 animate-bounce">
            {error}
          </div>
        )}

        {/* Bottom Controls */}
        <div className="w-full max-w-2xl py-6 flex flex-col items-center gap-4">
          {status === SessionStatus.CONNECTED ? (
            <div className="flex items-center gap-6 w-full justify-center">
              <button 
                onClick={disconnect}
                className="p-4 bg-slate-200 hover:bg-slate-300 text-slate-700 rounded-2xl transition-all"
                title="Disconnect"
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>

              <div className="flex-1 h-16 bg-white rounded-3xl border border-pink-100 shadow-inner flex items-center justify-center relative overflow-hidden">
                {isSpeaking ? (
                  <div className="flex items-center gap-1">
                    {[1,2,3,4,5].map(i => (
                      <div key={i} className={`w-1 bg-pink-400 rounded-full animate-pulse h-${i*2+2}`} />
                    ))}
                    <span className="text-xs font-medium text-pink-400 ml-2">Speaking...</span>
                  </div>
                ) : (
                  <div className="flex items-center gap-2">
                    <div className="w-2 h-2 bg-blue-400 rounded-full animate-ping" />
                    <span className="text-xs font-medium text-blue-400">Listening to you...</span>
                  </div>
                )}
              </div>
            </div>
          ) : null}
        </div>
      </main>

      {/* Footer Branding */}
      <footer className="p-2 text-center text-[10px] text-slate-400 opacity-50 font-varela uppercase tracking-widest">
        Anime Hindi Companion AI &bull; Powered by Gemini 2.5
      </footer>
    </div>
  );
};

export default App;

