import React, { useMemo } from 'react';
import { AudioFeatures } from '../App';

interface AvatarProps {
  isSpeaking: boolean;
  isListening: boolean;
  audioFeatures: AudioFeatures;
}

const Avatar: React.FC<AvatarProps> = ({ isSpeaking, isListening, audioFeatures }) => {
  const { volume, low, mid, high } = audioFeatures;

  // Map frequency bands to viseme properties
  // 'low' drives vertical opening (like O/U)
  // 'mid' drives vertical and some horizontal (like A)
  // 'high' drives horizontal widening (like E/I)

  const viseme = useMemo(() => {
    if (!isSpeaking) return { width: 12, height: 1.5, type: 'closed' };

    // Heuristic: determine primary mouth shape
    // A: Tall and Wide
    // E/I: Wide and Short
    // O/U: Narrow and Tall

    let baseWidth = 14;
    let baseHeight = 2;
    let roundness = 0.5;

    // Apply scaling based on bands
    // Horizontal wideness is influenced by mid/high
    const widthAdd = (mid * 15) + (high * 20);
    // Vertical height is influenced by low/mid
    const heightAdd = (low * 35) + (mid * 15);

    const finalWidth = Math.min(38, baseWidth + widthAdd);
    const finalHeight = Math.min(32, baseHeight + heightAdd);

    return { 
      width: finalWidth, 
      height: finalHeight,
      type: 'open' 
    };
  }, [isSpeaking, low, mid, high]);

  // Subtle randomized gestures when speaking
  const headRotation = useMemo(() => {
    if (!isSpeaking) return 0;
    return Math.sin(Date.now() / 250) * 1.5 + (low * 2);
  }, [isSpeaking, low]);

  const bodyLean = useMemo(() => {
    return Math.sin(Date.now() / 2000) * 0.5;
  }, []);

  const handY = useMemo(() => {
    if (!isSpeaking) return 465;
    return 465 - (volume * 25);
