      return;
    }

    const freqData = new Uint8Array(analyser.current.frequencyBinCount);
    analyser.current.getByteFrequencyData(freqData);

    let low = 0; 
    let mid = 0; 
    let high = 0; 

    for (let i = 0; i < 10; i++) low += freqData[i]; 
    for (let i = 10; i < 40; i++) mid += freqData[i];
    for (let i = 40; i < 120; i++) high += freqData[i];

    const lowNormalized = low / (10 * 255);
    const midNormalized = mid / (30 * 255);
    const highNormalized = high / (80 * 255);

    const currentVol = (lowNormalized + midNormalized + highNormalized) / 3;

    // Smooth energy tracking
    energyRef.current = energyRef.current * 0.9 + currentVol * 0.1;

    // Brightness ratio: helps distinguish 'bright/happy' voice vs 'dull/sad' voice
    const brightness = highNormalized / (lowNormalized + 0.01);

    setAudioFeatures({
      volume: currentVol,
      low: lowNormalized,
      mid: midNormalized,
      high: highNormalized,
      energy: energyRef.current,
      brightness: Math.min(1.5, brightness)
    });

    animationFrameRef.current = requestAnimationFrame(updateAudioAnalysis);
  }, [isSpeaking]);

  useEffect(() => {
    if (isSpeaking) {
      animationFrameRef.current = requestAnimationFrame(updateAudioAnalysis);
    } else {
      if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
      setAudioFeatures({ volume: 0, low: 0, mid: 0, high: 0, energy: 0, brightness: 0.5 });
      energyRef.current = 0;
    }
    return () => {
      if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
    };
  }, [isSpeaking, updateAudioAnalysis]);

  const stopAllAudio = useCallback(() => {
    activeSources.current.forEach(source => {
      try { source.stop(); } catch (e) {}
    });
    activeSources.current.clear();
    nextStartTime.current = 0;
    setIsSpeaking(false);
  }, []);

  const connectToLive = async () => {
    if (status === SessionStatus.CONNECTED) return;
    setStatus(SessionStatus.CONNECTING);
    setError(null);

    try {
      if (!inputAudioCtx.current) inputAudioCtx.current = new AudioContext({ sampleRate: 16000 });
      if (!outputAudioCtx.current) {
        outputAudioCtx.current = new AudioContext({ sampleRate: 24000 });
        analyser.current = outputAudioCtx.current.createAnalyser();
        analyser.current.fftSize = 512;
        analyser.current.connect(outputAudioCtx.current.destination);
      }

      if (inputAudioCtx.current.state === 'suspended') await inputAudioCtx.current.resume();
      if (outputAudioCtx.current.state === 'suspended') await outputAudioCtx.current.resume();

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setStatus(SessionStatus.CONNECTED);
            setIsListening(true);
            const source = inputAudioCtx.current!.createMediaStreamSource(stream);
            const processor = inputAudioCtx.current!.createScriptProcessor(4096, 1, 1);
            processor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = createPcmBlob(inputData);
              sessionPromise.then((session) => session.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(processor);
            processor.connect(inputAudioCtx.current!.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            const audioData = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData) {
              setIsSpeaking(true);
              const ctx = outputAudioCtx.current!;
              nextStartTime.current = Math.max(nextStartTime.current, ctx.currentTime);
              const audioBuffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(analyser.current!);
              source.addEventListener('ended', () => {
                activeSources.current.delete(source);
                if (activeSources.current.size === 0) setIsSpeaking(false);
              });
              source.start(nextStartTime.current);
              nextStartTime.current += audioBuffer.duration;
              activeSources.current.add(source);
            }
            if (message.serverContent?.interrupted) stopAllAudio();
            if (message.serverContent?.inputTranscription) currentInputTrans.current += message.serverContent.inputTranscription.text;
            if (message.serverContent?.outputTranscription) currentOutputTrans.current += message.serverContent.outputTranscription.text;
            if (message.serverContent?.turnComplete) {
              if (currentInputTrans.current) {
                setMessages(prev => [...prev, { id: Date.now().toString()+'-u', text: currentInputTrans.current, sender: 'user', timestamp: Date.now() }]);
              }
              if (currentOutputTrans.current) {
                setMessages(prev => [...prev, { id: Date.now().toString()+'-a', text: currentOutputTrans.current, sender: 'ai', timestamp: Date.now() }]);
              }
              currentInputTrans.current = '';
              currentOutputTrans.current = '';
            }
          },
          onerror: (e) => {
            setStatus(SessionStatus.ERROR);
            setError('Connection failed. Please check your network.');
          },
          onclose: () => {
            setStatus(SessionStatus.DISCONNECTED);
            setIsListening(false);
            stopAllAudio();
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
          systemInstruction: SYSTEM_INSTRUCTION,
          inputAudioTranscription: {},
          outputAudioTranscription: {}
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err) {
      setStatus(SessionStatus.ERROR);
      setError('Mic access denied or API failure.');
    }
  };

  const disconnect = () => {
    if (sessionRef.current) {
      sessionRef.current.close();
      sessionRef.current = null;
    }
    setStatus(SessionStatus.DISCONNECTED);
    setIsListening(false);
    stopAllAudio();
  };

  return (
    <div className="flex flex-col h-screen w-full bg-[#050505] text-white">
      {/* Immersive Background Elements */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none opacity-20">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-pink-900/30 blur-[120px] rounded-full" />
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-900/20 blur-[120px] rounded-full" />
      </div>

      {/* Subtle Top Status Bar */}
      <header className="p-6 flex items-center justify-between z-10">
        <div className="flex items-center gap-3">
          <div className="w-2 h-2 rounded-full bg-pink-500 shadow-[0_0_10px_rgba(236,72,153,0.5)]" />
          <h1 className="font-varela text-sm font-light tracking-widest text-pink-200/60 uppercase">
            Virtual Companion
          </h1>
        </div>

        {status === SessionStatus.CONNECTED && (
          <button onClick={disconnect} className="text-[10px] text-white/30 hover:text-white/60 transition-colors uppercase tracking-[0.2em]">
            Disconnect
          </button>
        )}
      </header>

      {/* Main Experience Area */}
      <main className="flex-1 flex flex-col items-center justify-center p-4 relative">
        {status === SessionStatus.DISCONNECTED || status === SessionStatus.ERROR ? (
          <div className="text-center space-y-8 z-10">
            <div className="space-y-4">
              <h2 className="text-4xl font-light tracking-tighter text-white/90">नमस्ते</h2>
              <p className="text-white/40 text-sm max-w-xs mx-auto leading-relaxed">
                क्या आप बात करने के लिए तैयार हैं? मैं आपकी बातें सुनने के लिए यहीं हूँ।
              </p>
            </div>
            <button 
              onClick={connectToLive}
              className="px-12 py-4 bg-white text-black font-bold rounded-full transition-all hover:scale-105 active:scale-95 shadow-[0_0_30px_rgba(255,255,255,0.2)]"
            >
              {status === SessionStatus.ERROR ? 'Retry' : 'Start Experience'}
            </button>
            {error && <p className="text-red-400 text-xs animate-pulse">{error}</p>}
          </div>
        ) : (
          <div className="w-full flex flex-col items-center">
            <Avatar isSpeaking={isSpeaking} isListening={isListening} audioFeatures={audioFeatures} />

            {/* Overlay Transcription (Subtle) */}
            <div className="absolute bottom-24 w-full max-w-lg px-8 pointer-events-none opacity-40">
              <Transcript messages={messages.slice(-1)} />
            </div>
          </div>
        )}

        {/* Live Audio Indicator */}
        {status === SessionStatus.CONNECTED && (
          <div className="absolute bottom-10 flex items-center gap-4">
            <div className="flex items-end gap-[3px] h-4">
              {[1,2,3,4,5,6].map(i => (
                <div 
                  key={i} 
                  className={`w-[2px] bg-white/40 rounded-full transition-all duration-150 ${isSpeaking ? 'animate-pulse' : ''}`}
                  style={{ height: isSpeaking ? `${Math.random() * 100}%` : '2px' }}
                />
              ))}
            </div>
            <span className="text-[10px] uppercase tracking-[0.3em] text-white/20">
              {isSpeaking ? 'Output' : 'Listening'}
            </span>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useMemo, useState, useEffect } from 'react';
import { AudioFeatures } from '../App';

interface AvatarProps {
  isSpeaking: boolean;
  isListening: boolean;
  audioFeatures: AudioFeatures;
}

const Avatar: React.FC<AvatarProps> = ({ isSpeaking, isListening, audioFeatures }) => {
  const { volume, low, mid, high, energy, brightness } = audioFeatures;

  // Blinking logic
  const [isBlinking, setIsBlinking] = useState(false);

  useEffect(() => {
    let blinkTimer: number;
    const performBlink = () => {
      setIsBlinking(true);
      setTimeout(() => setIsBlinking(false), 200);
      const baseDelay = isSpeaking || isListening ? 1500 : 3500;
      const randomDelay = Math.random() * 4000;
      blinkTimer = window.setTimeout(performBlink, baseDelay + randomDelay);
    };
    blinkTimer = window.setTimeout(performBlink, 3000);
    return () => clearTimeout(blinkTimer);
  }, [isSpeaking, isListening]);

  // Idle state management
  const [idleState, setIdleState] = useState({
    eyeOffsetX: 0,
    eyeOffsetY: 0,
    headTilt: 0,
    bodyShift: 0
  });

  useEffect(() => {
    const interval = setInterval(() => {
      const shouldMove = Math.random() > 0.6;
      if (shouldMove && !isSpeaking) {
        setIdleState({
          eyeOffsetX: (Math.random() - 0.5) * 8,
          eyeOffsetY: (Math.random() - 0.5) * 4,
          headTilt: (Math.random() - 0.5) * 4,
          bodyShift: (Math.random() - 0.5) * 2
        });
      } else if (isSpeaking) {
        setIdleState(prev => ({
          ...prev,
          eyeOffsetX: prev.eyeOffsetX * 0.4,
          eyeOffsetY: prev.eyeOffsetY * 0.4,
          headTilt: prev.headTilt * 0.8,
          bodyShift: 0
        }));
      }
    }, 2500);
    return () => clearInterval(interval);
  }, [isSpeaking]);

  // Emotional mapping:
  // Brightness > 1.0 indicates 'happy/excited'
  // Brightness < 0.6 indicates 'sad/soft'
  // Energy > 0.4 indicates 'intense/excited'

  const emotion = useMemo(() => {
    const happiness = Math.max(0, (brightness - 0.5) * 2);
    const intensity = energy * 2;
    const browRaise = (brightness > 1.0 ? 5 : 0) + (intensity > 0.5 ? 2 : 0);
    const browLower = brightness < 0.6 ? 3 : 0;

    return {
      smileFactor: Math.min(1.2, happiness),
      browY: -browRaise + browLower,
      eyeSquint: Math.min(1, volume * 1.5 + (intensity > 0.8 ? 0.2 : 0))
    };
  }, [brightness, energy, volume]);

  // Viseme mapping
  const viseme = useMemo(() => {
    if (!isSpeaking) return { width: 12, height: 1.5 };
    const baseWidth = 14 + (emotion.smileFactor * 10); // Wider mouth when 'happy'
    const baseHeight = 2;
    const widthAdd = (mid * 15) + (high * 20);
    const heightAdd = (low * 35) + (mid * 15);
    return { 
      width: Math.min(42, baseWidth + widthAdd), 
      height: Math.min(32, baseHeight + heightAdd)
    };
  }, [isSpeaking, low, mid, high, emotion.smileFactor]);

  const headRotation = useMemo(() => {
    const speed = 250 - (energy * 100); // Faster movement with high energy
    const speakMove = isSpeaking ? (Math.sin(Date.now() / speed) * (1.5 + energy * 3) + (low * 2)) : 0;
    return speakMove + idleState.headTilt;
  }, [isSpeaking, low, idleState.headTilt, energy]);

  const bodyLean = useMemo(() => {
    const naturalBreathe = Math.sin(Date.now() / 2000) * 0.5;
    return naturalBreathe + idleState.bodyShift;
  }, [idleState.bodyShift]);

  const handY = useMemo(() => {
    if (!isSpeaking) return 465;
    return 465 - (volume * 25) - (energy * 10);
  }, [isSpeaking, volume, energy]);

  return (
    <div className="relative w-full max-w-lg aspect-square flex items-center justify-center">
      {/* Glow */}
      <div className={`absolute w-[120%] h-[120%] rounded-full transition-all duration-1000 blur-[100px] ${
        isSpeaking ? 'bg-pink-500/10' : isListening ? 'bg-blue-500/10' : 'bg-white/5'
      }`} />

      <svg 
        viewBox="0 0 500 500" 
        className="w-full h-full drop-shadow-[0_0_50px_rgba(255,255,255,0.1)] overflow-visible"
      >
        <g style={{ transform: `rotate(${bodyLean}deg)`, transformOrigin: '250px 500px', transition: 'transform 1s ease-in-out' }}>
          <g style={{ transform: `rotate(${headRotation}deg)`, transformOrigin: '250px 380px', transition: 'transform 0.1s ease-out' }}>
            {/* Hair Back */}
            <path d="M150 150 Q250 100 350 150 L380 430 Q250 470 120 430 Z" fill="#121212" />

            {/* Body */}
            <g>
              <path d="M140 400 Q250 380 360 400 L430 500 L70 500 Z" fill="#eab308" opacity="0.9" />
              <circle cx="200" cy="450" r="10" fill="#fef3c7" opacity="0.2" />
              <circle cx="300" cy="470" r="8" fill="#fef3c7" opacity="0.15" />
            </g>

            {/* Neck */}
            <path d="M225 380 Q250 405 275 380 L270 420 Q250 430 230 420 Z" fill="#ffe4e1" />

            {/* Face */}
            <path d="M185 200 Q185 390 250 390 Q315 390 315 200 Q315 130 250 130 Q185 130 185 200 Z" fill="#fffafa" />

            {/* Brows */}
            <g transform={`translate(0, ${emotion.browY})`} style={{ transition: 'transform 0.15s ease-out' }}>
               {/* Left Brow */}
               <path d="M200 195 Q215 185 230 195" stroke="#222" strokeWidth="3" fill="none" strokeLinecap="round" />
               {/* Right Brow */}
               <path d="M270 195 Q285 185 300 195" stroke="#222" strokeWidth="3" fill="none" strokeLinecap="round" />
            </g>

            {/* Eyes Group */}
            <g className={isBlinking ? 'blink-active' : ''} style={{ transformOrigin: '250px 225px' }}>
              <g style={{ transform: `translate(${idleState.eyeOffsetX}px, ${idleState.eyeOffsetY}px)`, transition: 'transform 0.4s ease-in-out' }}>
                {/* Left Eye */}
                <g transform="translate(220, 225)">
                   <ellipse cx="0" cy="0" rx="14" ry={18 - (emotion.eyeSquint * 4)} fill="#222" />
                   <circle cx="4" cy="-7" r="4" fill="#fff" opacity="0.8" />
                </g>
                {/* Right Eye */}
                <g transform="translate(280, 225)">
                   <ellipse cx="0" cy="0" rx="14" ry={18 - (emotion.eyeSquint * 4)} fill="#222" />
                   <circle cx="4" cy="-7" r="4" fill="#fff" opacity="0.8" />
                </g>
              </g>
            </g>

            {/* Blush */}
            <circle cx="205" cy="275" r="12" fill="#ffc0cb" opacity={0.3 + (energy * 0.2)} />
            <circle cx="295" cy="275" r="12" fill="#ffc0cb" opacity={0.3 + (energy * 0.2)} />

            {/* Mouth */}
            <g transform="translate(250, 315)">
              {isSpeaking ? (
                <g>
                  {/* Mouth cavity - widens for smile */}
                  <ellipse 
                    cx="0" cy="0" 
                    rx={viseme.width} 
                    ry={viseme.height} 
                    fill="#700" 
                    style={{ transition: 'rx 0.05s ease-out, ry 0.05s ease-out' }}
                  />
                  <path 
                    d={`M -${viseme.width*0.5} ${viseme.height*0.2} Q 0 ${viseme.height*0.8} ${viseme.width*0.5} ${viseme.height*0.2}`} 
                    fill="#c00" opacity="0.5"
                  />
                  {/* Teeth */}
                  <path 
                    d={`M -${viseme.width*0.75} -${viseme.height*0.1} Q 0 -${viseme.height*(0.6 + emotion.smileFactor*0.2)} ${viseme.width*0.75} -${viseme.height*0.1}`} 
                    stroke="white" strokeWidth="2.5" fill="white" opacity="0.95"
                  />
                </g>
              ) : (
                <path d={`M -12 0 Q 0 ${6 + emotion.smileFactor*6} 12 0`} stroke="#333" strokeWidth="2.5" fill="none" strokeLinecap="round" style={{ transition: 'd 0.3s ease-out' }} />
              )}
            </g>

            {/* Hair Front */}
            <g fill="#121212">
              <path d="M185 155 Q250 120 315 155 Q300 190 280 170 Q250 215 220 170 Q200 190 185 155 Z" />
              <path d="M185 155 L160 390 Q170 405 190 380 Z" />
              <path d="M315 155 L340 390 Q330 405 310 380 Z" />
            </g>
          </g>

          {/* Hand Gestures */}
          <g style={{ transform: `translateY(${isSpeaking ? Math.sin(Date.now()/400)*3 : 0}px)` }}>
             <path 
               d={`M 180 500 Q 200 ${handY} 245 ${handY+15} Q 255 ${handY+35} 240 500`} 
               fill="#fffafa" 
               stroke="#ddd" 
               strokeWidth="0.5"
               opacity="0.9"
             />
          </g>
        </g>
      </svg>
      {isSpeaking && (
        <div className="absolute inset-0 pointer-events-none">
          <div className="absolute top-[65%] left-1/2 w-4 h-4 bg-white/5 rounded-full animate-ping" 
               style={{ transform: `translate(-50%, -50%) scale(${1 + volume * 2})` }} />
        </div>
      )}
    </div>
  );
};

export default Avatar;

