      });
      sessionRef.current = await sessionPromise;
    } catch (err) {
      setStatus(SessionStatus.ERROR);
      setError('Mic access denied or session failed.');
    }
  };

  const disconnect = () => {
    if (sessionRef.current) {
      sessionRef.current.close();
      sessionRef.current = null;
    }
    setStatus(SessionStatus.DISCONNECTED);
    setIsListening(false);
    activeSources.current.forEach(s => s.stop());
    activeSources.current.clear();
    setIsSpeaking(false);
  };

  return (
    <div className="flex flex-col h-screen w-full bg-[#1a0b1a] text-white overflow-hidden relative">
      {/* Immersive Magical Background */}
      <div className="absolute inset-0 pointer-events-none">
        <div className="absolute inset-0 bg-gradient-to-br from-[#4a1d4a] via-[#1a0b1a] to-[#2d0f2d] opacity-90" />
        <div className="absolute top-0 left-0 w-full h-full opacity-30 bg-[url('https://www.transparenttextures.com/patterns/stardust.png')] mix-blend-overlay" />
        <div className="absolute top-[-20%] left-[-20%] w-[60%] h-[60%] bg-pink-500/10 blur-[150px] rounded-full" />
        <div className="absolute bottom-[-20%] right-[-20%] w-[60%] h-[60%] bg-purple-500/10 blur-[150px] rounded-full" />
      </div>

      <header className="p-6 flex items-center justify-between z-10 relative">
        <div className="flex items-center gap-3">
          <div className="w-2.5 h-2.5 rounded-full bg-pink-400 shadow-[0_0_15px_pink] animate-pulse" />
          <h1 className="text-[10px] uppercase tracking-[0.4em] text-pink-200/40 font-varela">Fairy Sara Live</h1>
        </div>
        {status === SessionStatus.CONNECTED && (
          <button onClick={disconnect} className="text-[10px] text-pink-200/30 hover:text-pink-200/70 transition-colors tracking-[0.2em] uppercase">
            End Talk
          </button>
        )}
      </header>

      <main className="flex-1 flex flex-col items-center justify-center p-4 relative z-10">
        {status === SessionStatus.CONNECTED ? (
          <div className="w-full flex flex-col items-center">
            <Avatar isSpeaking={isSpeaking} isListening={isListening} audioFeatures={audioFeatures} />
            <div className="mt-12 max-w-lg w-full px-8 pointer-events-none">
              <Transcript messages={messages.slice(-1)} />
            </div>
          </div>
        ) : (
          <div className="text-center space-y-10">
            <div className="relative inline-block">
               <h2 className="text-5xl font-light tracking-tighter text-white/90">नमस्ते, मैं सारा हूँ</h2>
               <div className="absolute -top-6 -right-6 w-12 h-12 bg-pink-500/20 blur-xl rounded-full animate-pulse" />
            </div>
            <p className="text-pink-200/40 text-sm italic font-light tracking-wide">"Ek pyaari si jaadui mulaqat karein?"</p>
            <button 
              onClick={connectToLive} 
              className="px-12 py-4 bg-gradient-to-r from-pink-500 to-purple-600 text-white rounded-full font-bold hover:scale-105 transition-all shadow-[0_0_40px_rgba(236,72,153,0.3)] active:scale-95 border border-white/10"
            >
              {status === SessionStatus.CONNECTING ? 'Connecting...' : 'Start Magic'}
            </button>
            {error && <p className="text-red-400 text-xs mt-4 animate-bounce">{error}</p>}
          </div>
        )}
      </main>

      {/* Magical Particles Layer */}
      {status === SessionStatus.CONNECTED && (
        <div className="absolute inset-0 pointer-events-none overflow-hidden opacity-40">
           {Array.from({length: 15}).map((_, i) => (
             <div 
               key={i} 
               className="absolute bg-white rounded-full animate-pulse"
               style={{
                 left: `${Math.random() * 100}%`,
                 top: `${Math.random() * 100}%`,
                 width: `${Math.random() * 3 + 1}px`,
                 height: `${Math.random() * 3 + 1}px`,
                 animationDelay: `${Math.random() * 5}s`,
                 boxShadow: '0 0 8px white'
               }}
             />
           ))}
        </div>
      )}
    </div>
  );
};

