          </div>
        ) : (
          <div className="text-center space-y-10">
            <h2 className="text-5xl font-light tracking-tighter text-white/90">नमस्ते, मैं ज़ायरा हूँ</h2>
            <p className="text-pink-200/40 text-sm italic font-light tracking-wide">"Chalo Zyra ke saath kuch mazedaar banayein?"</p>
            <button 
              onClick={connectToLive} 
              className="px-12 py-4 bg-gradient-to-r from-pink-500 to-purple-600 text-white rounded-full font-bold hover:scale-105 transition-all shadow-[0_0_40px_rgba(236,72,153,0.3)] active:scale-95 border border-white/10"
            >
              {status === SessionStatus.CONNECTING ? 'Connecting...' : 'Start Session'}
            </button>
            {error && <p className="text-red-400 text-xs mt-4">{error}</p>}
