`;

export interface AudioFeatures {
  volume: number;
  low: number;
  mid: number;
  high: number;
  energy: number;
  brightness: number;
}

const App: React.FC = () => {
  const [status, setStatus] = useState<SessionStatus>(SessionStatus.DISCONNECTED);
  const [messages, setMessages] = useState<Message[]>([]);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [audioFeatures, setAudioFeatures] = useState<AudioFeatures>({ 
    volume: 0, low: 0, mid: 0, high: 0, energy: 0, brightness: 0.5 
  });

  // Navigation State: 'landing' | 'companion-setup' | 'teacher-setup' | 'active-session'
  const [view, setView] = useState<'landing' | 'companion-setup' | 'teacher-setup' | 'active-session'>('landing');
  const [activeMode, setActiveMode] = useState<'companion' | 'teacher'>('companion');

  // Teacher Mode State
  const [slides, setSlides] = useState<string[]>([]);
  const [currentSlideIndex, setCurrentSlideIndex] = useState(0);

  // Shared states
  const [timerValue, setTimerValue] = useState<number | null>(null);

  const inputAudioCtx = useRef<AudioContext | null>(null);
  const outputAudioCtx = useRef<AudioContext | null>(null);
  const analyser = useRef<AnalyserNode | null>(null);
  const nextStartTime = useRef<number>(0);
  const activeSources = useRef<Set<AudioBufferSourceNode>>(new Set());
  const currentInputTrans = useRef('');
  const currentOutputTrans = useRef('');
  const sessionRef = useRef<any>(null);
  const animationFrameRef = useRef<number | null>(null);
  const energyRef = useRef(0);

  const updateAudioAnalysis = useCallback(() => {
    if (!analyser.current || !isSpeaking) {
      setAudioFeatures({ volume: 0, low: 0, mid: 0, high: 0, energy: 0, brightness: 0.5 });
      energyRef.current = 0;
      return;
    }

    const freqData = new Uint8Array(analyser.current.frequencyBinCount);
    analyser.current.getByteFrequencyData(freqData);

    let low = 0, mid = 0, high = 0;
    for (let i = 0; i < 10; i++) low += freqData[i]; 
    for (let i = 10; i < 40; i++) mid += freqData[i];
    for (let i = 40; i < 120; i++) high += freqData[i];

    const lowNormalized = low / (10 * 255);
    const midNormalized = mid / (30 * 255);
    const highNormalized = high / (80 * 255);
    const currentVol = (lowNormalized + midNormalized + highNormalized) / 3;

    energyRef.current = energyRef.current * 0.9 + currentVol * 0.1;
    const brightness = highNormalized / (lowNormalized + 0.01);

    setAudioFeatures({
      volume: currentVol,
      low: lowNormalized,
      mid: midNormalized,
      high: highNormalized,
      energy: energyRef.current,
      brightness: Math.min(1.5, brightness)
    });

    animationFrameRef.current = requestAnimationFrame(updateAudioAnalysis);
  }, [isSpeaking]);

  useEffect(() => {
    if (isSpeaking) {
      animationFrameRef.current = requestAnimationFrame(updateAudioAnalysis);
    } else {
      if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
    }
    return () => { if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current); };
  }, [isSpeaking, updateAudioAnalysis]);

  useEffect(() => {
    let interval: number;
    if (timerValue !== null && timerValue > 0) {
      interval = window.setInterval(() => {
        setTimerValue(prev => (prev !== null && prev > 0 ? prev - 1 : 0));
      }, 1000);
    } else if (timerValue === 0) {
      setTimerValue(null);
      if (sessionRef.current) {
        sessionRef.current.sendRealtimeInput({ text: "The study break timer is complete! Let's resume." });
      }
    }
    return () => clearInterval(interval);
  }, [timerValue]);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;

    const base64Slides: string[] = [];
    for (let i = 0; i < Math.min(files.length, 5); i++) {
      const b64 = await blobToBase64(files[i]);
      base64Slides.push(b64);
    }
    setSlides(base64Slides);
    setCurrentSlideIndex(0);
  };

  const sendCurrentSlideToZyra = useCallback(() => {
    if (sessionRef.current && slides[currentSlideIndex]) {
      sessionRef.current.sendRealtimeInput({
        media: { data: slides[currentSlideIndex], mimeType: 'image/jpeg' }
      });
      sessionRef.current.sendRealtimeInput({ text: `Zyra, I am showing you Slide ${currentSlideIndex + 1}. Please teach me the content on this image verbally.` });
    }
  }, [currentSlideIndex, slides]);

  const connectToLive = async (mode: 'companion' | 'teacher') => {
    setStatus(SessionStatus.CONNECTING);
    setError(null);
    setActiveMode(mode);

    try {
      if (!inputAudioCtx.current) inputAudioCtx.current = new AudioContext({ sampleRate: 16000 });
      if (!outputAudioCtx.current) {
        outputAudioCtx.current = new AudioContext({ sampleRate: 24000 });
        analyser.current = outputAudioCtx.current.createAnalyser();
        analyser.current.fftSize = 512;
        analyser.current.connect(outputAudioCtx.current.destination);
      }

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setStatus(SessionStatus.CONNECTED);
            setIsListening(true);
            setView('active-session');
            const source = inputAudioCtx.current!.createMediaStreamSource(stream);
            const processor = inputAudioCtx.current!.createScriptProcessor(4096, 1, 1);
            processor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = createPcmBlob(inputData);
              sessionPromise.then((session) => session.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(processor);
            processor.connect(inputAudioCtx.current!.destination);

            if (mode === 'teacher' && slides.length > 0) {
              setTimeout(() => sendCurrentSlideToZyra(), 1200);
            }
          },
          onmessage: async (message: LiveServerMessage) => {
            const audioData = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData) {
              setIsSpeaking(true);
              const ctx = outputAudioCtx.current!;
              nextStartTime.current = Math.max(nextStartTime.current, ctx.currentTime);
              const audioBuffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(analyser.current!);
              source.addEventListener('ended', () => {
                activeSources.current.delete(source);
                if (activeSources.current.size === 0) setIsSpeaking(false);
              });
              source.start(nextStartTime.current);
              nextStartTime.current += audioBuffer.duration;
              activeSources.current.add(source);
            }
            if (message.serverContent?.interrupted) {
              activeSources.current.forEach(s => s.stop());
              activeSources.current.clear();
              nextStartTime.current = 0;
              setIsSpeaking(false);
            }

            if (message.serverContent?.outputTranscription) {
              const text = message.serverContent.outputTranscription.text;
              currentOutputTrans.current += text;
              if (text.includes("TIMER_START:")) {
                const match = text.match(/TIMER_START:\s*(\d+)/);
                if (match) setTimerValue(parseInt(match[1]));
              }
            }

            if (message.serverContent?.inputTranscription) currentInputTrans.current += message.serverContent.inputTranscription.text;
            if (message.serverContent?.turnComplete) {
              if (currentInputTrans.current) setMessages(p => [...p, { id: Date.now()+'-u', text: currentInputTrans.current, sender: 'user', timestamp: Date.now() }]);
              if (currentOutputTrans.current) setMessages(p => [...p, { id: Date.now()+'-a', text: currentOutputTrans.current, sender: 'ai', timestamp: Date.now() }]);
              currentInputTrans.current = '';
              currentOutputTrans.current = '';
            }
          },
          onclose: () => { 
            setStatus(SessionStatus.DISCONNECTED); 
            setIsListening(false); 
            setView('landing'); 
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
          systemInstruction: SYSTEM_INSTRUCTION,
          inputAudioTranscription: {},
          outputAudioTranscription: {}
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err) {
      setStatus(SessionStatus.ERROR);
      setError('Connection failed. Please check permissions.');
    }
  };

  const disconnect = () => {
    if (sessionRef.current) sessionRef.current.close();
    setStatus(SessionStatus.DISCONNECTED);
    setIsListening(false);
    activeSources.current.forEach(s => s.stop());
    activeSources.current.clear();
    setIsSpeaking(false);
    setTimerValue(null);
    setView('landing');
  };

  const nextSlide = () => {
    if (currentSlideIndex < slides.length - 1) {
      setCurrentSlideIndex(prev => prev + 1);
    }
  };

  const prevSlide = () => {
    if (currentSlideIndex > 0) {
      setCurrentSlideIndex(prev => prev - 1);
    }
  };

  useEffect(() => {
    if (status === SessionStatus.CONNECTED && activeMode === 'teacher') {
      sendCurrentSlideToZyra();
    }
  }, [currentSlideIndex, status, activeMode, sendCurrentSlideToZyra]);

  return (
    <div className="flex flex-col h-screen w-full bg-[#1a0b1a] text-white overflow-hidden relative font-outfit">
      {/* Background Layer */}
      <div className="absolute inset-0 pointer-events-none">
        <div className="absolute inset-0 bg-gradient-to-br from-[#4a1d4a] via-[#1a0b1a] to-[#2d0f2d] opacity-90" />
        <div className="absolute top-0 left-0 w-full h-full opacity-30 bg-[url('https://www.transparenttextures.com/patterns/stardust.png')] mix-blend-overlay" />
      </div>

      {/* Header */}
      <header className="p-6 flex items-center justify-between z-20 relative">
        <div className="flex items-center gap-3">
          <div className="w-2.5 h-2.5 rounded-full bg-pink-400 shadow-[0_0_15px_pink] animate-pulse" />
          <h1 className="text-[10px] uppercase tracking-[0.4em] text-pink-200/40 font-varela">Zyra Universe</h1>
        </div>
        {status === SessionStatus.CONNECTED && (
          <button onClick={disconnect} className="text-[10px] px-4 py-1.5 border border-pink-400/20 text-pink-200/40 hover:bg-pink-400/10 rounded-full transition-all uppercase tracking-widest">
            End Session
          </button>
        )}
      </header>

      <main className="flex-1 flex flex-col items-center justify-center p-4 relative z-10">

        {/* VIEW: LANDING PAGE */}
        {view === 'landing' && (
          <div className="text-center space-y-12 animate-in fade-in duration-700">
            <div className="space-y-4">
              <h2 className="text-6xl font-light tracking-tighter text-white/90">Zyra</h2>
              <p className="text-pink-200/40 text-sm italic">Choose your experience</p>
            </div>

            <div className="flex flex-col md:flex-row gap-6">
              <button 
                onClick={() => setView('companion-setup')}
                className="group relative w-64 p-8 bg-white/5 border border-pink-500/20 rounded-3xl hover:bg-pink-500/10 transition-all hover:scale-105"
              >
                <div className="text-3xl mb-4">✨</div>
                <h3 className="text-xl font-bold text-pink-300">Companion</h3>
                <p className="text-xs text-white/40 mt-2">Emotional, flirty, and playful baatein.</p>
              </button>

              <button 
                onClick={() => setView('teacher-setup')}
                className="group relative w-64 p-8 bg-white/5 border border-purple-500/20 rounded-3xl hover:bg-purple-500/10 transition-all hover:scale-105"
              >
                <div className="text-3xl mb-4">🎓</div>
                <h3 className="text-xl font-bold text-purple-300">Teacher</h3>
                <p className="text-xs text-white/40 mt-2">Verbal, professional learning with slides.</p>
              </button>
            </div>
          </div>
        )}

        {/* VIEW: COMPANION SETUP */}
        {view === 'companion-setup' && (
          <div className="text-center space-y-8 animate-in slide-in-from-bottom duration-500">
            <button onClick={() => setView('landing')} className="text-pink-200/30 text-xs hover:text-white uppercase tracking-widest">← Back</button>
            <h2 className="text-4xl font-light">Companion Mode</h2>
            <p className="text-pink-200/40 italic">"Chalo, thodi meethi baatein karein?"</p>
            <button 
              onClick={() => connectToLive('companion')}
              disabled={status === SessionStatus.CONNECTING}
              className="px-12 py-4 bg-gradient-to-r from-pink-500 to-purple-600 rounded-full font-bold shadow-lg shadow-pink-500/20 hover:scale-105 transition-all"
            >
              {status === SessionStatus.CONNECTING ? 'Connecting...' : 'Start Session'}
            </button>
          </div>
        )}

        {/* VIEW: TEACHER SETUP */}
        {view === 'teacher-setup' && (
          <div className="text-center space-y-8 animate-in slide-in-from-bottom duration-500 w-full max-w-md">
            <button onClick={() => setView('landing')} className="text-purple-200/30 text-xs hover:text-white uppercase tracking-widest">← Back</button>
            <h2 className="text-4xl font-light">Teacher Mode</h2>

            <div className="bg-white/5 border border-purple-500/20 p-8 rounded-3xl space-y-6">
              <p className="text-sm text-white/70">Upload your study material (max 5 images).</p>

              <label className="block w-full cursor-pointer bg-purple-600/10 hover:bg-purple-600/20 border-2 border-dashed border-purple-400/30 py-8 rounded-2xl transition-all">
                <span className="text-xs font-bold uppercase tracking-widest">
                  {slides.length > 0 ? `${slides.length} Slides Prepared` : 'Select Study Images'}
                </span>
                <input type="file" multiple accept="image/*" className="hidden" onChange={handleFileUpload} />
              </label>

              {slides.length > 0 && (
                <div className="flex gap-3 justify-center overflow-x-auto p-2 bg-black/20 rounded-xl">
                  {slides.map((s, i) => (
                    <img key={i} src={`data:image/jpeg;base64,${s}`} className="w-10 h-10 object-cover rounded-lg border border-white/20" />
                  ))}
                </div>
              )}
            </div>

            <button 
              onClick={() => connectToLive('teacher')}
              disabled={status === SessionStatus.CONNECTING || slides.length === 0}
              className={`px-12 py-4 rounded-full font-bold shadow-lg transition-all ${slides.length > 0 ? 'bg-gradient-to-r from-purple-500 to-indigo-600 hover:scale-105' : 'bg-white/10 text-white/20 cursor-not-allowed'}`}
            >
              {status === SessionStatus.CONNECTING ? 'Connecting...' : 'Start Learning'}
            </button>
          </div>
        )}

        {/* VIEW: ACTIVE SESSION */}
        {view === 'active-session' && (
          <div className="w-full h-full flex flex-col items-center animate-in fade-in duration-1000">
            <div className="relative flex flex-col md:flex-row items-center justify-center gap-12 w-full max-w-6xl">

              {/* Slide Display (Only in Teacher Mode) */}
              {activeMode === 'teacher' && slides.length > 0 && (
                <div className="w-full max-w-md aspect-[4/3] bg-black/40 border border-purple-500/30 rounded-3xl overflow-hidden relative shadow-2xl group order-2 md:order-1">
                  <img src={`data:image/jpeg;base64,${slides[currentSlideIndex]}`} alt="Study Material" className="w-full h-full object-contain" />
                  <div className="absolute top-4 left-4 px-3 py-1 bg-black/60 backdrop-blur-md rounded-full text-[10px] font-bold tracking-widest border border-white/10 uppercase">
                    Zyra Guru • Slide {currentSlideIndex + 1}/{slides.length}
                  </div>
                  <div className="absolute inset-y-0 left-0 right-0 flex items-center justify-between px-4 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button onClick={prevSlide} disabled={currentSlideIndex === 0} className="w-10 h-10 bg-black/60 rounded-full flex items-center justify-center hover:bg-black disabled:opacity-30">←</button>
                    <button onClick={nextSlide} disabled={currentSlideIndex === slides.length - 1} className="w-10 h-10 bg-black/60 rounded-full flex items-center justify-center hover:bg-black disabled:opacity-30">→</button>
                  </div>
                </div>
              )}

              {/* Avatar Section */}
              <div className="relative order-1 md:order-2">
                <Avatar isSpeaking={isSpeaking} isListening={isListening} audioFeatures={audioFeatures} />

                {/* Timer Display */}
                {timerValue !== null && (
                  <div className="absolute bottom-[-10px] left-1/2 -translate-x-1/2 px-8 py-2.5 bg-pink-500/90 backdrop-blur-md rounded-full shadow-[0_0_30px_pink] animate-pulse border border-white/20">
                    <span className="text-2xl font-bold tabular-nums">
                      {Math.floor(timerValue / 60)}:{String(timerValue % 60).padStart(2, '0')}
                    </span>
                  </div>
                )}
              </div>
            </div>

            {/* Minimal Subtitles / Transcription */}
            <div className="mt-16 max-w-2xl w-full px-8 opacity-60">
              <Transcript messages={messages.slice(-1)} />
            </div>
          </div>
        )}
      </main>

      {/* Decorative Particles for Session */}
      {status === SessionStatus.CONNECTED && (
        <div className="absolute inset-0 pointer-events-none overflow-hidden opacity-30">
          {Array.from({length: 20}).map((_, i) => (
            <div 
              key={i} 
              className="absolute bg-white rounded-full animate-pulse"
              style={{
                left: `${Math.random() * 100}%`,
                top: `${Math.random() * 100}%`,
                width: `${Math.random() * 2 + 1}px`,
                height: `${Math.random() * 2 + 1}px`,
                animationDelay: `${Math.random() * 5}s`,
                boxShadow: '0 0 10px white'
              }}
            />
          ))}
        </div>
      )}
    </div>
  );
};

export default App;

