      sessionRef.current.sendRealtimeInput({
        media: { data: slides[currentSlideIndex], mimeType: 'image/jpeg' }
      });
      sessionRef.current.sendRealtimeInput({ text: `Zyra, teaching slide ${currentSlideIndex + 1} now.` });
