                {timerValue !== null && (
                  <div className="absolute bottom-[-10px] left-1/2 -translate-x-1/2 px-6 py-1.5 bg-pink-600 rounded-full font-bold text-lg tabular-nums shadow-[0_0_20px_#db2777]">
                    {Math.floor(timerValue/60)}:{String(timerValue%60).padStart(2,'0')}
                  </div>
                )}
              </div>
              <div className="mt-8 opacity-40 text-center">
                <Transcript messages={messages.slice(-1)} />
              </div>
            </div>

            {activeMode === 'teacher' && slides.length > 0 && (
              <div className="flex-1 h-[70vh] max-w-5xl bg-[#111] rounded-3xl border border-white/10 overflow-hidden relative shadow-2xl flex flex-col">
                <div className="flex-1 bg-white relative overflow-hidden">
                  <img 
                    src={`data:image/jpeg;base64,${slides[currentSlideIndex]}`} 
