  const isSessionClosing = useRef(false);

  // Fix: Implemented slide navigation logic
  const goToNextSlide = useCallback(() => {
    setCurrentSlideIndex((prev) => (prev < slides.length - 1 ? prev + 1 : prev));
  }, [slides.length]);

  const goToPrevSlide = useCallback(() => {
    setCurrentSlideIndex((prev) => (prev > 0 ? prev - 1 : prev));
  }, []);

  // Fix: Implemented audio visualization and analysis for avatar reactivity
  const updateAudioAnalysis = useCallback(() => {
    if (!analyser.current || !isSpeaking) {
      setAudioFeatures({ volume: 0, low: 0, mid: 0, high: 0, energy: 0, brightness: 0.5 });
      energyRef.current = 0;
      return;
    }

    const freqData = new Uint8Array(analyser.current.frequencyBinCount);
    analyser.current.getByteFrequencyData(freqData);

    let low = 0, mid = 0, high = 0;
    for (let i = 0; i < 10; i++) low += freqData[i]; 
    for (let i = 10; i < 40; i++) mid += freqData[i];
    for (let i = 40; i < 120; i++) high += freqData[i];

    const lowNormalized = low / (10 * 255);
    const midNormalized = mid / (30 * 255);
    const highNormalized = high / (80 * 255);
    const currentVol = (lowNormalized + midNormalized + highNormalized) / 3;

    energyRef.current = energyRef.current * 0.9 + currentVol * 0.1;
    const brightness = highNormalized / (lowNormalized + 0.01);

    setAudioFeatures({
      volume: currentVol,
      low: lowNormalized,
      mid: midNormalized,
      high: highNormalized,
      energy: energyRef.current,
      brightness: Math.min(1.5, brightness)
    });

    animationFrameRef.current = requestAnimationFrame(updateAudioAnalysis);
  }, [isSpeaking]);

  useEffect(() => {
    if (isSpeaking) {
      animationFrameRef.current = requestAnimationFrame(updateAudioAnalysis);
    } else {
      if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
    }
    return () => { if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current); };
  }, [isSpeaking, updateAudioAnalysis]);

  useEffect(() => {
    let interval: number;
    if (timerValue !== null && timerValue > 0) {
      interval = window.setInterval(() => {
        setTimerValue(prev => (prev !== null && prev > 0 ? prev - 1 : 0));
      }, 1000);
    } else if (timerValue === 0) {
      setTimerValue(null);
      if (sessionRef.current && !isSessionClosing.current) {
        sessionRef.current.sendRealtimeInput({ text: "Break timer finished. Let's get back to work!" });
      }
    }
    return () => clearInterval(interval);
  }, [timerValue]);

  // Fix: Completed file upload handling for teaching slides
  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;

    const base64Slides: string[] = [];
    for (let i = 0; i < Math.min(files.length, 5); i++) {
      const b64 = await blobToBase64(files[i]);
      base64Slides.push(b64);
    }
    setSlides(base64Slides);
    setCurrentSlideIndex(0);
  };

  // Fix: Implemented sending visual context to Zyra
  const sendCurrentSlideToZyra = useCallback(() => {
    if (sessionRef.current && slides[currentSlideIndex] && !isSessionClosing.current) {
      sessionRef.current.sendRealtimeInput({
        media: { data: slides[currentSlideIndex], mimeType: 'image/jpeg' }
      });
      sessionRef.current.sendRealtimeInput({ text: `Zyra, please look at this slide (Slide ${currentSlideIndex + 1}) and explain it in detail. Don't rush. When you are totally finished with the explanation, only then suggest moving to the next one.` });
    }
  }, [currentSlideIndex, slides]);

  // Fix: Re-implemented connectToLive following Gemini Live API best practices
  const connectToLive = async () => {
    setStatus(SessionStatus.CONNECTING);
    setError(null);
    isSessionClosing.current = false;

    try {
      if (!inputAudioCtx.current) inputAudioCtx.current = new AudioContext({ sampleRate: 16000 });
      if (!outputAudioCtx.current) {
        outputAudioCtx.current = new AudioContext({ sampleRate: 24000 });
        analyser.current = outputAudioCtx.current.createAnalyser();
        analyser.current.fftSize = 512;
        analyser.current.connect(outputAudioCtx.current.destination);
      }

      if (inputAudioCtx.current.state === 'suspended') await inputAudioCtx.current.resume();
      if (outputAudioCtx.current.state === 'suspended') await outputAudioCtx.current.resume();

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      // Fix: Initializing fresh client for Live API as per guidelines
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setStatus(SessionStatus.CONNECTED);
            setIsListening(true);
            setView('active-session');

            const source = inputAudioCtx.current!.createMediaStreamSource(stream);
            scriptProcessorRef.current = inputAudioCtx.current!.createScriptProcessor(4096, 1, 1);

            scriptProcessorRef.current.onaudioprocess = (e) => {
              if (isSessionClosing.current || status !== SessionStatus.CONNECTED) return;
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = createPcmBlob(inputData);
              // Fix: Crucial step to ensure session data is sent after promise resolution
              sessionPromise.then((session) => {
                if (session && !isSessionClosing.current) {
                  try {
                    session.sendRealtimeInput({ media: pcmBlob });
                  } catch (err) { console.error(err); }
                }
              });
            };
            source.connect(scriptProcessorRef.current);
            scriptProcessorRef.current.connect(inputAudioCtx.current!.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            // Fix: Handled audio stream decoding and playback scheduling
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setIsSpeaking(true);
              nextStartTime.current = Math.max(nextStartTime.current, outputAudioCtx.current!.currentTime);
              const audioBuffer = await decodeAudioData(decode(base64Audio), outputAudioCtx.current!, 24000, 1);
              const source = outputAudioCtx.current!.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(analyser.current!);
              source.addEventListener('ended', () => {
                activeSources.current.delete(source);
                if (activeSources.current.size === 0) setIsSpeaking(false);
              });
              source.start(nextStartTime.current);
              nextStartTime.current += audioBuffer.duration;
              activeSources.current.add(source);
            }

            // Fix: Handled audio interruptions gracefully
            if (message.serverContent?.interrupted) {
              activeSources.current.forEach(s => { try { s.stop(); } catch(e){} });
              activeSources.current.clear();
              nextStartTime.current = 0;
              setIsSpeaking(false);
            }

            // Fix: Handled real-time transcriptions and navigation tokens
            if (message.serverContent?.inputTranscription) {
              currentInputTrans.current += message.serverContent.inputTranscription.text;
            }
            if (message.serverContent?.outputTranscription) {
              currentOutputTrans.current += message.serverContent.outputTranscription.text;
              if (currentOutputTrans.current.includes('MOVE_TO_NEXT_SLIDE')) {
                pendingSlideAction.current = 'next';
              } else if (currentOutputTrans.current.includes('MOVE_TO_PREVIOUS_SLIDE')) {
                pendingSlideAction.current = 'prev';
              }
            }

            if (message.serverContent?.turnComplete) {
              const userMsg: Message = { id: Date.now().toString(), text: currentInputTrans.current, sender: 'user', timestamp: Date.now() };
              const cleanAiText = currentOutputTrans.current.replace(/MOVE_TO_(NEXT|PREVIOUS)_SLIDE/g, '').trim();
              const aiMsg: Message = { id: (Date.now() + 1).toString(), text: cleanAiText, sender: 'ai', timestamp: Date.now() };

              setMessages(prev => [...prev, userMsg, aiMsg].slice(-10));
              currentInputTrans.current = '';
              currentOutputTrans.current = '';

              if (pendingSlideAction.current === 'next') {
                goToNextSlide();
                pendingSlideAction.current = null;
              } else if (pendingSlideAction.current === 'prev') {
                goToPrevSlide();
                pendingSlideAction.current = null;
              }
            }
          },
          onerror: (e) => {
            console.error('Live API Error:', e);
            setError("Summoning Zyra failed. Please check your connection.");
            setStatus(SessionStatus.ERROR);
          },
          onclose: () => {
            setStatus(SessionStatus.DISCONNECTED);
            setIsListening(false);
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } }
          },
          systemInstruction: SYSTEM_INSTRUCTION,
          inputAudioTranscription: {},
          outputAudioTranscription: {}
        }
      });

      sessionRef.current = await sessionPromise;
    } catch (err) {
      console.error(err);
      setError("Failed to establish magical connection.");
      setStatus(SessionStatus.ERROR);
    }
  };

  // Fix: Implemented clean disconnect logic
  const disconnect = useCallback(() => {
    isSessionClosing.current = true;
    if (sessionRef.current) {
      sessionRef.current.close();
      sessionRef.current = null;
    }
    if (scriptProcessorRef.current) {
      scriptProcessorRef.current.disconnect();
      scriptProcessorRef.current = null;
    }
    setStatus(SessionStatus.DISCONNECTED);
    setIsListening(false);
    setView('landing');
  }, []);

  useEffect(() => {
    return () => {
      isSessionClosing.current = true;
      if (sessionRef.current) sessionRef.current.close();
      if (scriptProcessorRef.current) scriptProcessorRef.current.disconnect();
    };
  }, []);

  // Fix: Implemented Landing View UI
  if (view === 'landing') {
    return (
      <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center p-8 text-white font-sans overflow-hidden">
        <div className="max-w-2xl w-full space-y-12 text-center animate-in fade-in slide-in-from-bottom-8 duration-1000">
          <div className="space-y-4">
            <h1 className="text-7xl font-bold tracking-tighter bg-gradient-to-r from-pink-400 via-purple-400 to-indigo-400 bg-clip-text text-transparent">
              Zyra
            </h1>
            <p className="text-slate-400 text-xl font-light">Your Magical Fairy AI Companion & Teacher</p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 h-64">
            <button 
              onClick={() => { setActiveMode('companion'); connectToLive(); }}
              disabled={status === SessionStatus.CONNECTING}
              className="group relative overflow-hidden rounded-2xl border border-white/10 bg-white/5 p-8 transition-all hover:bg-white/10 hover:scale-105 active:scale-95"
            >
              <div className="relative z-10 space-y-4">
                <span className="text-4xl">🦋</span>
                <h2 className="text-2xl font-semibold">Companion</h2>
                <p className="text-sm text-slate-500">Playful conversation & bonding</p>
              </div>
              <div className="absolute inset-0 bg-gradient-to-br from-pink-500/10 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
            </button>

            <div className="group relative overflow-hidden rounded-2xl border border-white/10 bg-white/5 p-8 transition-all hover:bg-white/10 hover:scale-105">
              <div className="relative z-10 space-y-4 flex flex-col items-center">
                <span className="text-4xl">🎓</span>
                <h2 className="text-2xl font-semibold">Teacher</h2>
                <input 
                  type="file" 
                  multiple 
                  accept="image/*" 
                  onChange={(e) => { handleFileUpload(e); setActiveMode('teacher'); connectToLive(); }}
                  className="absolute inset-0 opacity-0 cursor-pointer"
                />
                <p className="text-sm text-slate-500">Upload slides to start learning</p>
              </div>
              <div className="absolute inset-0 bg-gradient-to-br from-purple-500/10 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
            </div>
          </div>

          {status === SessionStatus.CONNECTING && (
            <div className="animate-pulse text-pink-400 font-medium">Summoning Zyra...</div>
          )}
        </div>
      </div>
    );
  }

  // Fix: Implemented Active Session View UI
  return (
    <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-between p-6 text-white overflow-hidden relative">
      <div className="absolute top-8 left-8 flex items-center gap-4">
        <div className={`w-3 h-3 rounded-full ${status === SessionStatus.CONNECTED ? 'bg-green-500 shadow-[0_0_10px_#22c55e]' : 'bg-red-500 animate-pulse'}`} />
        <span className="text-sm font-mono tracking-widest text-slate-500 uppercase">{status}</span>
      </div>

      <div className="absolute top-8 right-8 flex gap-4">
        {activeMode === 'teacher' && (
          <div className="bg-white/5 px-4 py-2 rounded-full border border-white/10 text-xs font-medium text-slate-400">
            SLIDE {currentSlideIndex + 1} / {slides.length}
          </div>
        )}
        <button 
          onClick={disconnect}
          className="bg-white/5 px-6 py-2 rounded-full border border-white/10 text-xs font-medium hover:bg-red-500/20 hover:border-red-500/50 transition-all active:scale-95"
        >
          DISCONNECT
        </button>
      </div>

      <div className="flex-1 w-full max-w-6xl flex flex-col md:flex-row items-center justify-center gap-12 mt-12">
        {activeMode === 'teacher' && slides.length > 0 && (
          <div className="w-full md:w-1/2 flex flex-col gap-6 animate-in slide-in-from-left duration-700">
            <div className="relative aspect-video rounded-3xl overflow-hidden border border-white/10 shadow-2xl bg-slate-900 group">
              <img src={`data:image/jpeg;base64,${slides[currentSlideIndex]}`} alt="Current Slide" className="w-full h-full object-contain" />
              <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity flex items-end p-6">
                <div className="flex gap-2">
                  <button onClick={goToPrevSlide} className="p-3 bg-white/10 hover:bg-white/20 rounded-xl">◀</button>
                  <button onClick={goToNextSlide} className="p-3 bg-white/10 hover:bg-white/20 rounded-xl">▶</button>
                  <button onClick={sendCurrentSlideToZyra} className="px-6 py-3 bg-purple-500/80 hover:bg-purple-500 rounded-xl font-medium">Ask Zyra to Explain</button>
                </div>
              </div>
            </div>
            <div className="flex justify-center gap-4">
               {timerValue !== null && (
                 <div className="text-3xl font-bold font-mono text-pink-400 bg-pink-500/10 px-6 py-2 rounded-2xl border border-pink-500/20 animate-bounce">
                   BREAK: {Math.floor(timerValue / 60)}:{(timerValue % 60).toString().padStart(2, '0')}
                 </div>
               )}
            </div>
          </div>
        )}

        <div className={`flex flex-col items-center justify-center gap-8 ${activeMode === 'teacher' ? 'md:w-1/2' : 'w-full'}`}>
          <Avatar 
            isSpeaking={isSpeaking} 
            isListening={isListening} 
            audioFeatures={audioFeatures}
          />
          <div className="h-24 w-full flex items-center justify-center">
            <Transcript messages={messages} />
          </div>
        </div>
      </div>

      <div className="w-full max-w-4xl flex items-center justify-center gap-12 pb-12">
          {activeMode === 'teacher' && (
            <button 
              onClick={() => {
                setTimerValue(300);
                if (sessionRef.current && !isSessionClosing.current) {
                  sessionRef.current.sendRealtimeInput({ text: "Zyra, let's take a 5 minute break." });
                }
              }}
              className="p-4 rounded-full bg-white/5 border border-white/10 hover:bg-blue-500/20 hover:border-blue-500/50 transition-all group"
            >
              <span className="text-2xl group-hover:scale-110 transition-transform block">⏳</span>
            </button>
          )}

          <div className="relative group">
            <div className={`absolute -inset-4 bg-gradient-to-r from-pink-500/20 to-purple-500/20 rounded-full blur-xl opacity-0 transition-opacity ${isListening ? 'opacity-100 animate-pulse' : ''}`} />
            <div className={`relative z-10 w-20 h-20 rounded-full flex items-center justify-center transition-all ${isListening ? 'bg-pink-500 scale-110' : 'bg-white/10 hover:bg-white/20'}`}>
              {isListening ? (
                <div className="flex gap-1 items-center">
                  {[1,2,3].map(i => <div key={i} className="w-1 bg-white rounded-full animate-wave" style={{ height: `${12 + Math.random() * 12}px`, animationDelay: `${i * 0.1}s` }} />)}
                </div>
              ) : (
                <span className="text-2xl opacity-50">🎙️</span>
              )}
            </div>
          </div>

          <button 
            onClick={() => {
               if (sessionRef.current && !isSessionClosing.current) {
                 sessionRef.current.sendRealtimeInput({ text: "Zyra, tell me a joke!" });
               }
            }}
            className="p-4 rounded-full bg-white/5 border border-white/10 hover:bg-pink-500/20 hover:border-pink-500/50 transition-all group"
          >
            <span className="text-2xl group-hover:scale-110 transition-transform block">✨</span>
          </button>
      </div>

      {error && (
        <div className="absolute bottom-8 left-1/2 -translate-x-1/2 bg-red-500/20 border border-red-500/50 px-6 py-3 rounded-full text-red-400 text-sm font-medium animate-in slide-in-from-bottom-4">
          {error}
        </div>
      )}
    </div>
  );
};

// Fix: Added the missing default export
export default App;
